+///|
+fn progress_json_text(text : String, truncated : Ref[Bool]) -> String {
+  if !text.contains("\u001b") {
+    return text
+  }
+  let parts : Array[String] = []
+  for line in text.split("\n") {
+    match terminal_text(line.to_owned()) {
+      Some(safe) => parts.push(safe)
+      None => {
+        truncated.val = true
+        return "[unavailable]"
+      }
+    }
+  }
+  parts.join("\n")
+}
