+///|
+fn progress_normalize_json(
+  value : Json,
+  truncated : Ref[Bool],
+  depth : Int32,
+) -> Json {
+  if depth >= 64 {
+    truncated.val = true
+    return Json::string("[unavailable]")
+  }
+  match value {
+    Json::String(text) => Json::string(progress_json_text(text, truncated))
+    Json::Array(values) =>
+      Json::array(
+        values.map(item => progress_normalize_json(item, truncated, depth + 1)),
+      )
+    Json::Object(values) => {
+      let result = Json::empty_object()
+      for name, item in values {
+        let key = progress_json_text(name, truncated)
+        if field(result, key) is Some(_) {
+          truncated.val = true
+        } else {
