 85	///|
 86	fn credential_word(c : Char) -> Bool {
 87	  (c >= 'a' && c <= 'z') ||
 88	  (c >= 'A' && c <= 'Z') ||
 89	  (c >= '0' && c <= '9') ||
 90	  c == '_' ||
 91	  c == '-'
 92	}
 93	
 94	///|
 95	fn credential_space(c : Char) -> Bool {
 96	  c == ' ' || c == '\t'
 97	}
 98	
 99	///|
100	fn credential_end(c : Char) -> Bool {
101	  credential_space(c) ||
102	  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
103	}
