144	///|
145	fn redact_credentials(
146	  text : String,
147	  for_diagnostics~ : Bool = true,
148	  incomplete? : Ref[Bool],
149	) -> String {
150	  let chars = text.iter().to_array()
151	  let buffer = @buffer.Buffer(size_hint=text.length())
152	  let mut i = 0
153	  let mut url = false
154	  while i < chars.length() {
155	    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
156	      url = false
157	    }
158	    if chars[i] == ':' &&
159	      i + 2 < chars.length() &&
160	      chars[i + 1] == '/' &&
161	      chars[i + 2] == '/' {
162	      url = true
163	      buffer.write_string_utf8("://")
164	      i += 3
165	      let mut end = i
166	      let mut user_end = None
167	      while end < chars.length() &&
168	            !credential_end(chars[end]) &&
169	            !['/', '?'].contains(chars[end]) {
170	        if chars[end] == '@' {
171	          user_end = Some(end)
172	        }
173	        end += 1
174	      }
175	      if user_end is Some(end) {
176	        buffer.write_string_utf8("[redacted]@")
177	        i = end + 1
178	      }
179	      continue
180	    }
181	    if url && ['?', '&'].contains(chars[i]) {
182	      let start = i
183	      i += 1
184	      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
185	        i += 1
186	      }
187	      let name = credential_parameter(character_text(chars, start + 1, i))
188	      if i < chars.length() && chars[i] == '=' {
189	        i += 1
190	        buffer.write_string_utf8(character_text(chars, start, i))
191	        if credential_field(name, for_diagnostics~) ||
192	          name.to_lower() == "key" ||
193	          (for_diagnostics && name.to_lower() == "code") {
194	          if i + 10 <= chars.length() &&
195	            character_text(chars, i, i + 10) == "[redacted]" {
196	            i += 10
197	          }
198	          while i < chars.length() && !credential_end(chars[i]) {
199	            i += 1
200	          }
201	          buffer.write_string_utf8("[redacted]")
202	        }
203	      } else {
204	        buffer.write_string_utf8(character_text(chars, start, i))
205	      }
206	      continue
207	    }
208	    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
209	      let start = i
210	      let mut end = i
211	      while end < chars.length() && credential_word(chars[end]) {
212	        end += 1
213	      }
214	      let word = character_text(chars, start, end)
215	      let lower = word.to_lower()
216	      if [
217	          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
218	        ]
219	        .iter()
220	        .any(prefix => lower.has_prefix(prefix)) ||
221	        (for_diagnostics && lower.has_prefix("glpat-")) ||
222	        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
223	        while end < chars.length() && !credential_end(chars[end]) {
224	          end += 1
225	        }
226	        buffer.write_string_utf8("[redacted]")
227	        i = end
228	        continue
229	      }
230	      let mut separator = end
231	      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
232	        separator += 1
233	      }
234	      while separator < chars.length() && credential_space(chars[separator]) {
235	        separator += 1
236	      }
237	      if for_diagnostics &&
238	        ["bearer", "basic"].contains(lower) &&
239	        separator > end &&
240	        separator < chars.length() {
241	        let mut value_end = separator
242	        if separator + 10 <= chars.length() &&
243	          character_text(chars, separator, separator + 10) == "[redacted]" {
244	          value_end = separator + 10
245	        }
246	        while value_end < chars.length() && !credential_end(chars[value_end]) {
247	          value_end += 1
248	        }
249	        let value = character_text(chars, separator, value_end).to_lower()
250	        if value_end > separator &&
251	          !["authentication", "auth", "token"].contains(value) {
252	          buffer.write_string_utf8(character_text(chars, start, separator))
253	          buffer.write_string_utf8("[redacted]")
254	          i = value_end
255	          continue
256	        }
257	      }
258	      let mut previous = start
259	      while previous > 0 && credential_space(chars[previous - 1]) {
260	        previous -= 1
261	      }
262	      let field_start = previous == 0 ||
263	        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
264	      let option = word.has_prefix("--")
265	      let prose_credential = (
266	          ["credential", "credentials"].contains(lower) && !field_start
267	        ) ||
268	        (for_diagnostics && lower == "ssh_inject_git_credentials")
269	      let assignment = separator < chars.length() &&
270	        (
271	          chars[separator] == '=' ||
272	          (chars[separator] == ':' && !prose_credential)
273	        )
274	      if credential_field(word, for_diagnostics~) &&
275	        (assignment || (option && separator > end)) {
276	        let mut value = if assignment { separator + 1 } else { separator }
277	        while value < chars.length() && credential_space(chars[value]) {
278	          value += 1
279	        }
280	        buffer.write_string_utf8(character_text(chars, start, value))
281	        let quoted_key = start > 0 &&
282	          end < chars.length() &&
283	          ['"', '\''].contains(chars[start - 1]) &&
284	          chars[start - 1] == chars[end]
285	        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
286	          buffer.write_string_utf8("[redacted]")
287	          let mut boundary = chars.length()
288	          if lower != "set-cookie" {
289	            let mut cursor = value
290	            while cursor < chars.length() {
291	              if chars[cursor] == ';' {
292	                let mut start = cursor + 1
293	                while start < chars.length() && credential_space(chars[start]) {
294	                  start += 1
295	                }
296	                let mut end = start
297	                while end < chars.length() && chars[end] != ';' {
298	                  end += 1
299	                }
300	                let segment = character_text(chars, start, end)
301	                if !segment.contains("=") &&
302	                  segment.iter().any(credential_space) {
303	                  boundary = cursor
304	                  break
305	                }
306	              }
307	              cursor += 1
308	            }
309	          }
310	          if boundary == chars.length() && incomplete is Some(flag) {
311	            flag.val = true
312	          }
313	          i = boundary
314	        } else if value + 10 <= chars.length() &&
315	          character_text(chars, value, value + 10) == "[redacted]" {
316	          buffer.write_string_utf8("[redacted]")
317	          i = value + 10
318	          while i < chars.length() && !credential_end(chars[i]) {
319	            i += 1
320	          }
321	        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
322	          let quote = chars[value]
323	          buffer.write_char_utf8(quote)
324	          value += 1
325	          while value < chars.length() && chars[value] != quote {
326	            if chars[value] == '\\' && value + 1 < chars.length() {
327	              value += 1
328	            }
329	            value += 1
330	          }
331	          buffer.write_string_utf8("[redacted]")
332	          i = value
333	        } else {
334	          let mut value_end = value
335	          while value_end < chars.length() && !credential_end(chars[value_end]) {
336	            value_end += 1
337	          }
338	          let scheme = character_text(chars, value, value_end).to_lower()
339	          if scheme == "bearer" || scheme == "basic" {
340	            while value_end < chars.length() &&
341	                  credential_space(chars[value_end]) {
342	              value_end += 1
343	            }
344	            buffer.write_string_utf8(character_text(chars, value, value_end))
345	            value = value_end
346	            while value_end < chars.length() &&
347	                  !credential_end(chars[value_end]) {
348	              value_end += 1
349	            }
350	          }
351	          if value + 10 <= chars.length() &&
352	            character_text(chars, value, value + 10) == "[redacted]" {
353	            value_end = value + 10
354	          }
355	          if value_end > value {
356	            buffer.write_string_utf8("[redacted]")
357	          }
358	          i = value_end
359	        }
360	        continue
361	      }
362	      buffer.write_string_utf8(word)
363	      i = end
364	      continue
365	    }
366	    buffer.write_char_utf8(chars[i])
367	    i += 1
368	  }
369	  @utf8.decode_lossy(buffer.to_bytes())
370	}

