1088	fn diagnostic_error(
1089	  error : Error,
1090	  environment? : Map[String, String],
1091	) -> String {
1092	  let (message, omitted) = match error {
1093	    AdapterError(detail) => (detail, false)
1094	    InvalidConfig(detail) => (detail, false)
1095	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
1096	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
1097	    @json.InvalidNumber(position, _) =>
1098	      (
1099	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
1100	        true,
1101	      )
1102	    _ => (error.to_string(), false)
1103	  }
1104	  diagnostic_text(message, environment?, omitted~)
1105	}
