1107	///|
1108	fn diagnostic_text(
1109	  message : String,
1110	  environment? : Map[String, String],
1111	  omitted~ : Bool = false,
1112	  protected_secrets? : Array[String],
1113	  incomplete_final_line~ : Bool = false,
1114	) -> String {
1115	  let progress = Progress::new("diagnostic-error", environment?)
1116	  if protected_secrets is Some(values) {
1117	    for value in values {
1118	      add_protected_secret(progress.secrets, value)
1119	    }
1120	  }
1121	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
1122	  let lines = []
1123	  let mut incomplete = omitted
1124	  let source_lines = message.split("\n").to_array()
1125	  for index in 0..<source_lines.length() {
1126	    let line = source_lines[index]
1127	    if lines.length() == 32 {
1128	      incomplete = true
1129	      ignore(lines.remove(1))
1130	    }
1131	    let truncated = line.length() > 1024
1132	    let bounded = if truncated {
1133	      incomplete = true
1134	      line[:1024].to_owned()
1135	    } else {
1136	      line.to_owned()
1137	    }
1138	    let bounded = if truncated ||
1139	      (incomplete_final_line && index == source_lines.length() - 1) {
1140	      diagnostic_partial_secret(bounded, progress.secrets)
1141	    } else {
1142	      bounded
1143	    }
1144	    match progress.safe_message(bounded) {
1145	      Some(safe) => lines.push(safe)
1146	      None => {
1147	        incomplete = true
1148	        lines.push("[unavailable]")
1149	      }
1150	    }
1151	  }
1152	  if (incomplete || progress.details_truncated) &&
1153	    lines.last() != Some("[error details incomplete or truncated]") {
1154	    lines.push("[error details incomplete or truncated]")
1155	  }
1156	  lines.join("\n")
1157	}
