1159	///|
1160	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
1161	  let chars = text.iter().to_array()
1162	  let mut boundary = chars.length()
1163	  for secret in secrets {
1164	    let value = secret.iter().to_array()
1165	    if value.length() == 0 || text.has_suffix(secret) {
1166	      continue
1167	    }
1168	    let limit = if value.length() - 1 < boundary {
1169	      value.length() - 1
1170	    } else {
1171	      boundary
1172	    }
1173	    if limit == 0 {
1174	      continue
1175	    }
1176	    let prefixes = FixedArray::make(limit, 0)
1177	    let mut matched = 0
1178	    for index in 1..<limit {
1179	      while matched > 0 && value[matched] != value[index] {
1180	        matched = prefixes[matched - 1]
1181	      }
1182	      if value[matched] == value[index] {
1183	        matched += 1
1184	      }
1185	      prefixes[index] = matched
1186	    }
1187	    matched = 0
1188	    for index in 0..<boundary {
1189	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1190	        matched = prefixes[matched - 1]
1191	      }
1192	      if matched < limit && value[matched] == chars[index] {
1193	        matched += 1
1194	      }
1195	    }
1196	    boundary -= matched
1197	  }
1198	  if boundary == chars.length() {
1199	    text
1200	  } else {
1201	    character_text(chars, 0, boundary) + "[redacted]"
1202	  }
1203	}
