1212	///|
1213	fn diagnostic_add_protected(
1214	  value : String,
1215	  output : String,
1216	  uncertain : Bool,
1217	  destination : Array[String],
1218	  result : DiagnosticProtectedValues,
1219	) -> Unit {
1220	  if value == "" ||
1221	    (
1222	      !output.contains(value) &&
1223	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
1224	    ) {
1225	    return
1226	  }
1227	  if result.secrets.length() >= 512 {
1228	    result.incomplete = true
1229	    return
1230	  }
1231	  destination.push(value)
1232	}
