1234	///|
1235	fn diagnostic_protected_values(
1236	  value : Json,
1237	  result : DiagnosticProtectedValues,
1238	  output : String,
1239	  uncertain : Bool,
1240	  secret~ : Bool = false,
1241	  depth~ : Int32 = 0,
1242	) -> Unit {
1243	  if result.visited >= 65536 || depth >= 64 {
1244	    result.incomplete = true
1245	    return
1246	  }
1247	  result.visited += 1
1248	  match value {
1249	    Json::String(text) if text != "" && secret => {
1250	      let destination = result.secrets
1251	      diagnostic_add_protected(text, output, uncertain, destination, result)
1252	      for line in text.split("\n") {
1253	        if line != "" && line.length() < text.length() {
1254	          diagnostic_add_protected(
1255	            line.to_owned(),
1256	            output,
1257	            uncertain,
1258	            destination,
1259	            result,
1260	          )
1261	        }
1262	        for word in line.split(" ") {
1263	          for part in word.split("=") {
