448	      }
449	      progress_message("Build " + id.to_owned() + ": " + detail)
450	    } else if classic_build_step(safe) {
451	      // Classic RUN output has no prefix. Only its own completion marker
452	      // ends this mode; phase events on another pipe can arrive ahead of it.
453	      self.classic_build = true
454	      progress_message("Build " + safe)
455	    } else if safe.has_prefix("Successfully built ") ||
456	      safe.has_prefix("Successfully tagged ") {
457	      self.classic_build = false
458	      progress_message("Build: " + safe)
459	    } else if self.classic_build && !warning {
