122	///|
123	fn sensitive_name(name : String) -> Bool {
124	  let normalized = name.to_lower().replace_all(old="-", new="_")
125	  if normalized == "ssh_auth_sock" {
126	    return false
127	  }
128	  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
129	    .iter()
130	    .any(suffix => normalized.has_suffix(suffix)) {
131	    return false
132	  }
133	  let credential = credential_field(name, for_diagnostics=true)
134	  let name = name.to_lower()
135	  credential ||
136	  [
137	    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
138	    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
139	  ]
140	  .iter()
141	  .any(marker => name.contains(marker))
142	}
