144	///|
145	fn add_protected_secret(secrets : Array[String], value : String) -> Unit {
146	  if value == "" {
147	    return
148	  }
149	  let values = [value]
150	  for part in value.split("\n") {
151	    if part.trim() != "" && part.length() < value.length() {
152	      values.push(part.to_owned())
153	    }
154	  }
155	  for item in values {
156	    if !secrets.contains(item) {
157	      secrets.push(item)
158	    }
159	    let encoded = Json::string(item).stringify()
160	    let escaped = encoded[1:encoded.length() - 1].to_owned()
161	    if escaped != item && !secrets.contains(escaped) {
162	      secrets.push(escaped)
163	    }
164	  }
165	}
