167	///|
168	fn Progress::new(
169	  stage : String,
170	  environment? : Map[String, String],
171	  recording_override? : Bool,
172	  context? : Json,
173	  protected_secrets? : Array[String],
174	  protection_incomplete~ : Bool = false,
175	) -> Progress {
176	  let secrets = []
177	  for name, value in environment.unwrap_or(@env.get_env_vars()) {
178	    if sensitive_name(name) && value != "" {
179	      // Multiline credentials must also be masked in line-oriented output.
180	      add_protected_secret(secrets, value)
181	    }
182	  }
183	  if protected_secrets is Some(values) {
184	    for value in values {
185	      add_protected_secret(secrets, value)
186	    }
187	  }
188	  for value in create_recording.protected_secrets {
189	    add_protected_secret(secrets, value)
190	  }
191	  secrets.sort_by((a, b) => b.length().compare(a.length()))
192	  {
193	    stage,
194	    operations: {},
195	    builds: {},
196	    secrets,
197	    protection_incomplete: protection_incomplete ||
198	    create_recording.protection_incomplete,
199	    recording: recording_override.unwrap_or(
200	      environment.unwrap_or(@env.get_env_vars()).get("ORCA_ENV_DEVSY_RECORDING") !=
201	      Some("0"),
202	    ),
203	    context,
204	    phase_count: 0,
205	    private_key: false,
206	    classic_build: false,
207	    recent: [],
208	    failures: [],
209	    unrecognized: [],
210	    details_truncated: false,
211	  }
212	}
