248	///|
249	fn Progress::remember(
250	  self : Progress,
251	  message : String,
252	  warning~ : Bool,
253	) -> Unit {
254	  let lines = if warning { self.failures } else { self.recent }
255	  if lines.last() == Some(message) {
256	    return
257	  }
258	  if lines.length() == 8 {
259	    ignore(lines.remove(0))
260	    self.details_truncated = true
261	  }
262	  lines.push(message)
263	}
