265	///|
266	fn Progress::failure_detail(self : Progress) -> String {
267	  let lines = self.failures +
268	    self.recent.filter(line => !self.failures.contains(line))
269	  let detail = if lines.is_empty() {
270	    "no readable error message from subprocess"
271	  } else {
272	    lines.join("\n")
273	  }
274	  detail +
275	  (if self.details_truncated {
276	    "\n[error details incomplete or truncated]"
277	  } else {
278	    ""
279	  })
280	}
