283	fn Progress::remember_unrecognized(self : Progress, text : String) -> Unit {
284	  if self.protection_incomplete {
285	    self.details_truncated = true
286	    let unavailable = "error detail unavailable because workspace protection values could not be read"
287	    if !self.unrecognized.contains(unavailable) {
288	      self.unrecognized.push(unavailable)
289	    }
290	    return
291	  }
292	  guard self.safe_message(text) is Some(safe) else {
293	    self.details_truncated = true
294	    return
295	  }
296	  if self.unrecognized.length() == 8 {
297	    ignore(self.unrecognized.remove(0))
298	    self.details_truncated = true
299	  }
300	  self.unrecognized.push(safe)
301	}
