317	///|
318	async fn Progress::status(self : Progress, event : Json) -> Unit {
319	  guard field(event, "phase") is Some(Json::String(phase)) &&
320	    phase_label(phase) is Some(label) &&
321	    field(event, "state") is Some(Json::String(state)) &&
322	    ["started", "succeeded", "failed", "skipped"].contains(state) else {
323	    return
324	  }
325	  if self.phase_count < 128 {
326	    self.phase_count += 1
327	    save_diagnostic(
328	      self.stage,
329	      state,
330	      phase~,
331	      error_type?=if state == "failed" { Some("backend_phase") } else { None },
332	      evidence?=self.context,
333	      evidence_stable_operation=true,
334	      protected_secrets=self.secrets,
335	      recording=self.recording,
336	    )
337	  } else if self.phase_count == 128 {
338	    self.phase_count += 1
339	    self.details_truncated = true
340	    save_diagnostic(
341	      self.stage,
342	      "diagnostics-truncated",
343	      error_type="phase_limit",
344	      phase~,
345	      evidence?=self.context,
346	      evidence_incomplete=true,
347	      evidence_stable_operation=true,
348	      protected_secrets=self.secrets,
349	      recording=self.recording,
350	    )
351	  }
352	  let key = ["pipeline", "operationId", "phase", "step"]
353	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
354	    .join(":")
355	  if state == "started" {
356	    if self.operations.length() >= 256 {
357	      self.operations.clear()
358	    }
359	    self.operations.set(key, @env.now())
360	    progress_message(label + ": running…")
361	  } else {
362	    let duration = match field(event, "durationMs") {
363	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
364	        Some(seconds(value.to_uint64()))
365	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
366	    }
367	    self.operations.remove(key)
368	    let timing = duration.map(value => value + ", ").unwrap_or("") +
369	      "elapsed " +
370	      seconds(@env.now() - progress_started)
371	    progress_message(
372	      label +
373	      ": " +
374	      (if state == "succeeded" { "done" } else { state }) +
375	      " (" +
376	      timing +
377	      ")",
378	    )
379	  }
380	}
