382	///|
383	fn classic_build_step(text : String) -> Bool {
384	  guard text.has_prefix("Step ") &&
385	    text[5:].split_once("/") is Some((step, rest)) &&
386	    rest.split_once(" ") is Some((total, detail)) else {
387	    return false
388	  }
389	  step.length() > 0 &&
390	  total.length() > 0 &&
391	  step.iter().all(c => c >= '0' && c <= '9') &&
392	  total.iter().all(c => c >= '0' && c <= '9') &&
393	  detail.trim().has_prefix(":")
394	}
