   133	  let credential = credential_field(name, for_diagnostics=true)
   134	  let name = name.to_lower()
   135	  credential ||
   136	  [
   137	    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
   138	    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
   139	  ]
   140	  .iter()
