   214	///|
   215	fn terminal_text(text : String) -> String? {
   216	  let output = @buffer.Buffer(size_hint=256)
   217	  let mut state = 0
   218	  for c in text.iter() {
   219	    match state {
   220	      0 =>
   221	        if c == '\u001b' {
   222	          state = 1
   223	        } else if c.to_int() < 32 && c != '\t' {
   224	          return None
   225	        } else {
   226	          output.write_char_utf8(c)
   227	        }
   228	      1 =>
   229	        if c == '[' {
   230	          state = 2
   231	        } else if c == ']' {
   232	          state = 3
   233	        } else {
   234	          return None
   235	        }
   236	      2 => if c >= '@' && c <= '~' { state = 0 }
   237	      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
   238	      _ => if c == '\\' { state = 0 } else { state = 3 }
   239	    }
   240	  }
   241	  if state != 0 {
   242	    None
   243	  } else {
   244	    Some(@utf8.decode_lossy(output.to_bytes()))
   245	  }
   246	}
