   469	///|
   470	fn Progress::learn_event(self : Progress, event : Json, line : String) -> Unit {
   471	  if event != Json::null() {
   472	    let protected_values : DiagnosticProtectedValues = {
   473	      secrets: [],
   474	      visited: 0,
   475	      incomplete: false,
   476	    }
   477	    diagnostic_protected_values(event, protected_values, line, false)
   478	    if protected_values.incomplete ||
   479	      self.secrets.length() + protected_values.secrets.length() > 1024 {
   480	      self.protection_incomplete = true
   481	      self.details_truncated = true
   482	      self.recent.clear()
   483	      self.failures.clear()
   484	      self.unrecognized.clear()
   485	    } else {
   486	      for secret in protected_values.secrets {
   487	        add_protected_secret(self.secrets, secret)
   488	      }
   489	      self.secrets.sort_by((a, b) => b.length().compare(a.length()))
   490	    }
   491	  }
   492	}
