   512	///|
   513	fn progress_normalize_json(
   514	  value : Json,
   515	  truncated : Ref[Bool],
   516	  depth : Int32,
   517	) -> Json {
   518	  if depth >= 64 {
   519	    truncated.val = true
   520	    return Json::string("[unavailable]")
   521	  }
   522	  match value {
   523	    Json::String(text) => Json::string(progress_json_text(text, truncated))
   524	    Json::Array(values) =>
   525	      Json::array(
   526	        values.map(item => progress_normalize_json(item, truncated, depth + 1)),
   527	      )
   528	    Json::Object(values) => {
   529	      let result = Json::empty_object()
   530	      for name, item in values {
   531	        let key = progress_json_text(name, truncated)
   532	        if field(result, key) is Some(_) {
   533	          truncated.val = true
   534	        } else {
   535	          set_field(
   536	            result,
   537	            key,
   538	            progress_normalize_json(item, truncated, depth + 1),
   539	          )
   540	        }
   541	      }
   542	      result
   543	    }
   544	    _ => value
   545	  }
   546	}
