   603	///|
   604	async fn Progress::line(
   605	  self : Progress,
   606	  line : String,
   607	  statuses~ : Bool,
   608	  messages~ : Bool,
   609	) -> Unit {
   610	  if line.trim() == "" {
   611	    return
   612	  }
   613	  let event = @json.parse(line) catch { _ => Json::null() }
   614	  if field(event, "kind") == Some(Json::string("status")) {
   615	    if field(event, "state") == Some(Json::string("failed")) &&
   616	      field(event, "error") is Some(error) {
   617	      for name in ["message", "hint"] {
   618	        if field(error, name) is Some(Json::String(text)) {
   619	          self.message(
   620	            text,
   621	            debug=false,
   622	            warning=true,
   623	            emit=messages || statuses,
   624	          )
   625	        }
   626	      }
   627	      self.remember_unrecognized_json(event)
   628	    }
   629	    if statuses || messages {
   630	      self.status(event)
   631	    }
   632	    return
   633	  }
   634	  // Result envelopes and arbitrary structured responses are never log text.
   635	  if field(event, "kind") == Some(Json::string("result")) {
   636	    if field(event, "outcome") == Some(Json::string("success")) &&
   637	      field(event, "warnings") is Some(Json::Array(warnings)) {
   638	      for warning in warnings {
   639	        match warning {
   640	          Json::String(text) =>
   641	            self.message(
   642	              text,
   643	              debug=false,
   644	              warning=true,
   645	              emit=messages || statuses,
   646	            )
   647	          _ => {
   648	            let truncated : Ref[Bool] = { val: false, }
   649	            let safe = diagnostic_json(warning, {}, self.secrets, truncated, 0).stringify()
   650	            if truncated.val {
   651	              self.details_truncated = true
   652	            }
   653	            self.message(safe, debug=false, warning=true, emit=false)
   654	          }
   655	        }
   656	      }
   657	    }
   658	    if field(event, "outcome") != Some(Json::string("success")) &&
   659	      (
   660	        field(event, "error") is Some(_) ||
   661	        field(event, "message") is Some(_) ||
   662	        field(event, "code") is Some(_) ||
   663	        field(event, "outcome") == Some(Json::string("failure")) ||
   664	        field(event, "outcome") == Some(Json::string("error"))
   665	      ) {
   666	      self.remember_unrecognized_json(event)
   667	    }
   668	    return
   669	  }
   670	  if field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
   671	    return
   672	  }
   673	  if event is Json::Object(_) {
   674	    let kind = field(event, "kind")
   675	    guard kind == None ||
   676	      kind == Some(Json::string("log")) ||
   677	      kind == Some(Json::string("error")) else {
   678	      self.remember_unrecognized_json(event)
   679	      return
   680	    }
   681	    let message = match field(event, "msg") {
   682	      Some(value) => Some(value)
   683	      None =>
   684	        match field(event, "message") {
   685	          Some(value) => Some(value)
   686	          None =>
   687	            match field(event, "error") {
   688	              Some(Json::Object(_) as value) => field(value, "message")
   689	              value => value
   690	            }
   691	        }
   692	    }
   693	    guard message is Some(Json::String(text)) else {
   694	      self.remember_unrecognized_json(event)
   695	      return
   696	    }
   697	    let level = field(event, "level")
   698	    self.message(
   699	      text,
   700	      debug=level == Some(Json::string("debug")) ||
   701	        level == Some(Json::string("trace")),
   702	      warning=kind == Some(Json::string("error")) ||
   703	        level == Some(Json::string("warn")) ||
   704	        level == Some(Json::string("error")),
   705	      emit=messages || (statuses && kind != None),
   706	    )
   707	  } else {
   708	    if event != Json::null() {
   709	      self.remember_unrecognized_json(event)
   710	      return
   711	    }
   712	    // Malformed JSON and binary output are not a safe free-text fallback.
   713	    let text = line.trim().to_owned()
   714	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
   715	      self.message(text, debug=false, warning=true, emit=messages)
   716	      return
   717	    }
   718	    if text.has_prefix("{") || text.has_prefix("[") {
   719	      self.details_truncated = true
   720	      self.remember_unrecognized(text)
   721	      return
   722	    }
   723	    self.message(
   724	      text,
   725	      debug=text.contains(" DEBUG ") ||
   726	        text.contains(" TRACE ") ||
   727	        text.has_prefix("DEBUG ") ||
   728	        text.has_prefix("TRACE "),
   729	      warning=text.contains(" WARN ") ||
   730	        text.contains(" ERROR ") ||
   731	        text.has_prefix("WARN ") ||
   732	        text.has_prefix("ERROR "),
   733	      emit=messages,
   734	    )
   735	  }
   736	}
