   772	///|
   773	async fn Progress::read_output(
   774	  self : Progress,
   775	  reader : @process.ReadFromProcess,
   776	  capture~ : Bool,
   777	  statuses~ : Bool = false,
   778	  messages~ : Bool = false,
   779	  raw_messages~ : Bool = false,
   780	) -> String {
   781	  let output = @buffer.Buffer(size_hint=4096)
