   793	        tail = tail[tail.length() - 8192:].to_owned()
   794	      }
   795	    }
   796	    for byte in chunk {
   797	      if byte == b'\n' || byte == b'\r' {
   798	        if oversized && scanner is Some(current) {
   799	          current.feed(@utf8.decode_lossy(pending.to_bytes()))
   800	          private_key.val = current.finish()
   801	          scanner = None
   802	        } else if pending.length() > 0 {
   803	          let malformed : Ref[Bool] = { val: false, }
   804	          let line = @utf8.decode(pending.to_bytes()) catch {
   805	            _ => {
   806	              self.details_truncated = true
   807	              malformed.val = true
   808	              @utf8.decode_lossy(pending.to_bytes())
   809	            }
   810	          }
   811	          if malformed.val {
   812	            let current = PrivateKeyScanner::new(private_key.val)
   813	            current.feed(line)
   814	            private_key.val = current.finish()
   815	          } else if self.filter_output_line(line, private_key) is Some(safe) {
   816	            if raw_messages {
   817	              self.message(safe, debug=false, warning=true, emit=false)
   818	            } else if capture {
   819	              self.line(safe, statuses~, messages~)
   820	            } else {
   821	              self.stderr_line(safe, statuses~, messages~)
   822	            }
   823	          }
   824	        }
   825	        pending.reset()
   826	        oversized = false
   827	      } else if !oversized {
   828	        if pending.length() == 65536 {
   829	          let current = PrivateKeyScanner::new(private_key.val)
   830	          current.feed(@utf8.decode_lossy(pending.to_bytes()))
   831	          scanner = Some(current)
   832	          pending.reset()
   833	          pending.write_byte(byte)
   834	          oversized = true
   835	          self.details_truncated = true
   836	        } else {
   837	          pending.write_byte(byte)
   838	        }
   839	      } else {
   840	        pending.write_byte(byte)
   841	        if pending.length() >= 4096 && scanner is Some(current) {
   842	          current.feed(@utf8.decode_lossy(pending.to_bytes()))
   843	          pending.reset()
   844	        }
   845	      }
   846	    }
   847	  }
   848	  if oversized && scanner is Some(current) {
   849	    current.feed(@utf8.decode_lossy(pending.to_bytes()))
   850	    private_key.val = current.finish()
