681	          secrets,
682	          evidence_truncated,
683	          0,
684	          stable_activity=evidence_stable_activity,
685	        ),
686	      )
687	    } else {
688	      evidence_truncated.val = true
689	    }
690	  }
691	  if evidence is Some(value) {
692	    if value.stringify().length() <= 65536 {
693	      set_field(
694	        event,
695	        "evidence",
696	        diagnostic_json(
697	          value,
698	          process_environment,
699	          secrets,
700	          evidence_truncated,
701	          0,
702	          stable_activity=evidence_stable_activity,
703	          secret_states=stage == "server-environment",
704	          stable_operation=evidence_stable_operation,
705	          stable_arguments=[
