707	          ].contains(stage),
708	        ),
709	      )
710	    } else {
711	      evidence_truncated.val = true
712	    }
713	  }
714	  if evidence_truncated.val {
715	    set_field(event, "evidenceTruncated", Json::boolean(true))
716	    set_field(event, "completeness", Json::string("partial"))
717	  }
718	  if details_truncated ||
719	    evidence_truncated.val ||
720	    field(event, "detailsTruncated") == Some(Json::boolean(true)) {
721	    diagnostic_recording_health.run_partial = true
722	  }
723	  if run_completeness is Some(value) {
724	    set_field(event, "runCompleteness", Json::string(value))
725	  }
726	  if os_errno is Some(code) && code > 0 && code < 4096 {
727	    set_field(event, "osErrno", Json::number(code.to_double()))
728	  }
729	  if exit_code is Some(code) {
730	    set_field(event, "exitCode", Json::number(code.to_double()))
731	  }
732	  for pair in [("errorType", error_type), ("phase", phase)] {
733	    if pair.1 is Some(text) {
734	      set_field(event, pair.0, Json::string(text))
735	    }
736	  }
737	  if duration_ms is Some(value) {
738	    set_field(event, "durationMs", Json::number(value))
739	  }
740	  if attempt is Some(value) {
741	    set_field(event, "attempt", Json::number(value.to_double()))
742	  }
743	  if timeout_ms is Some(value) {
744	    set_field(event, "timeoutMs", Json::number(value.to_double()))
745	  }
746	  if retry_delay_ms is Some(value) {
747	    set_field(event, "retryDelayMs", Json::number(value.to_double()))
748	  }
749	  let failed = error_type is Some(_) ||
750	    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
751	      status,
752	    )
753	  if diagnostic_pending.length() >= 64 {
754	    let mut evict = -1
755	    if failed {
756	      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
757	        if !diagnostic_pending[index].failed {
758	          evict = index
759	          break
760	        }
761	      }
762	      if evict < 0 &&
763	        diagnostic_pending_inflight.val < diagnostic_pending.length() {
764	        evict = diagnostic_pending_inflight.val
765	      }
766	    }
767	    if evict < 0 {
768	      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
769	      return
770	    }
771	    let removed = diagnostic_pending.remove(evict)
772	    diagnostic_pending.push({ event, failed, time: event_time, })
773	    diagnostic_recording_failed(
774	      "buffer_full",
775	      phase="buffer",
776	      event_time=removed.time,
777	    )
778	    try_flush_diagnostic_recording()
779	    return
780	  }
781	  diagnostic_pending.push({ event, failed, time: event_time, })
782	  try_flush_diagnostic_recording()
783	}
