   166	        diagnostic_output(
   167	          stderr,
   168	          environment,
   169	          protected_input?=input,
   170	          protect_all_input=true,
   171	          protected_secrets?,
   172	          omitted=stderr_truncated,
   173	        )
   174	      }
   175	      if !stderr_truncated && !protection_incomplete {
   176	        try {
   177	          let error = @json.parse(@utf8.decode(stderr))
   178	          let reported_phase = required(error, "phase")
   179	          let reported_code = required(error, "code")
   180	          if [
   181	              "load", "read", "normalize", "input", "profile", "write", "verify",
   182	            ].contains(reported_phase) &&
   183	            ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
   184	              reported_code,
   185	            ) {
   186	            phase = reported_phase
   187	            code = reported_code
   188	            let kind = match field(error, "kind") {
   189	              Some(Json::String(value)) if [
   190	                  "Error", "TypeError", "SyntaxError", "ReferenceError", "RangeError",
   191	                  "AssertionError", "URIError",
   192	                ].contains(value) => Some(value)
   193	              _ => None
   194	            }
   195	            let native_code = match field(error, "nativeCode") {
   196	              Some(Json::String(value)) if value.length() > 0 &&
   197	                value.length() <= 64 &&
   198	                value
   199	                .iter()
   200	                .all(c => {
   201	                  (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
   202	                }) => Some(value)
   203	              _ => None
   204	            }
   205	            detail = if kind is Some(kind) {
   206	              Some(
   207	                kind +
   208	                native_code.map(value => " (" + value + ")").unwrap_or(""),
   209	              )
   210	            } else {
   211	              None
   212	            }
   213	            for
   214	              name in (if native_code == Some("MODULE_NOT_FOUND") {
   215	                ["target", "missing", "cause", "location", "message", "path"]
   216	              } else {
   217	                ["target", "cause", "location", "message", "path"]
   218	              }) {
   219	              if field(error, name) is Some(Json::String(value)) &&
   220	                value.length() > 0 &&
   221	                value.length() <= 1024 &&
   222	                diagnostic_output(
   223	                  @utf8.encode(value),
   224	                  environment,
   225	                  protected_input?=input,
   226	                  protect_all_input=true,
   227	                  protected_secrets?,
   228	                  omitted=field(error, "detailsTruncated") ==
   229	                    Some(Json::boolean(true)) &&
   230	                    (name == "message" || name == "path" || name == "missing"),
   231	                )
   232	                is Some(safe) {
   233	                detail = Some(
   234	                  detail.unwrap_or("Error") + " " + name + "=" + safe,
   235	                )
   236	              }
   237	            }
   238	            if field(error, "detailsTruncated") == Some(Json::boolean(true)) {
   239	              detail = Some(
   240	                detail.unwrap_or("Error") +
   241	                "\n[error details incomplete or truncated]",
   242	              )
   243	            }
   244	          }
   245	        } catch {
   246	          _ => ()
   247	        }
   248	      }
   249	      if write_error is Some(error) {
   250	        detail = Some(
   251	          detail.unwrap_or("Process exited without readable stderr") +
   252	          "\nInput transfer failed: " +
   253	          diagnostic_error(error, environment~),
   254	        )
   255	      }
   256	      if stdout_truncated {
   257	        detail = Some(incomplete_diagnostic_detail(detail))
   258	      }
   259	      raise SettingsProcessError(phase, code, status, detail)
   260	    }
   261	    if write_error is Some(error) {
   262	      raise error
   263	    }
   264	    if diagnostic_stage is Some(stage) &&
   265	      (stderr.length() > 0 || stderr_truncated) {
   266	      let detail = if protection_incomplete {
   267	        Some(
   268	          "error detail unavailable because workspace protection values could not be read\n[error details incomplete or truncated]",
   269	        )
   270	      } else {
   271	        diagnostic_output(
   272	          stderr,
   273	          environment,
   274	          protected_input?=input,
   275	          protect_all_input=true,
   276	          protected_secrets?,
   277	          omitted=stderr_truncated,
   278	        )
   279	      }
   280	      if detail is Some(detail) {
   281	        save_diagnostic(
   282	          stage,
   283	          "warning",
   284	          phase=diagnostic_phase,
   285	          error_message=detail,
   286	          details_truncated=stderr_truncated || protection_incomplete,
   287	          environment~,
   288	          protected_secrets?,
   289	          recording?,
   290	        )
   291	      }
   292	    }
   293	    guard !stdout_truncated else {
   294	      raise AdapterError("Orca settings result exceeds size limit")
   295	    }
   296	    @utf8.decode(stdout)
   297	  })
   298	}
