 57	    )
 58	    try {
 59	      if @fs.exists(path) {
 60	        @fs.read_file(path).text()
 61	      } else {
 62	        ""
 63	      }
 64	    } catch {
 65	      @os_error.OSError(code, ..) as error => {
 66	        os_errno = Some(code)
