273	///|
274	async fn bulk_one(mode : String, state : Json, options : BulkOptions) -> Json? {
275	  let id = required(state, "workspaceId")
276	  let saved_secrets = saved_workspace_secrets(state)
277	  let secrets = saved_secrets.unwrap_or([])
278	  if saved_secrets is None {
279	    suppress_workspace_recording(state)
280	  }
281	  let result : Json = {
282	    "id": id,
283	    "uid": required(state, "workspaceUid"),
284	    "context": required(state, "context"),
285	    "provider": options.provider,
286	    "identityVerified": false,
287	    "vmStatus": "unknown",
288	    "activity": "unknown",
289	    "outcome": "skipped",
290	  }
291	  let mut mutating = false
292	  try {
293	    set_field(result, "autoStop", idle_status(state))
294	    let effective_context = bulk_context(state)
295	    guard required(state, "context") == effective_context else {
296	      save_diagnostic(
297	        "bulk-workspace",
298	        "excluded",
299	        evidence={
300	          "id": id,
301	          "savedContext": required(state, "context"),
302	          "effectiveContext": effective_context,
303	          "reason": "context_mismatch",
304	        },
305	        protected_secrets=secrets,
306	        environment=workspace_environment(state),
307	        recording=operation_recording(state),
308	      )
309	      return None
310	    }
311	    let lock = connection_operation_lock(state, validate=false)
312	    defer lock.close()
313	    snapshot_workspace_recording(state, required(state, "tunnelDirectory"))
314	    match saved_workspace_secrets(state) {
315	      Some(values) =>
316	        for secret in values {
317	          secrets.push(secret)
318	        }
319	      None => suppress_workspace_recording(state)
320	    }
321	    validate_connection_owner(state)
322	    let (in_scope, matched) = bulk_identity(state, options.provider)
323	    guard in_scope else { return None }
324	    set_field(result, "identityVerified", Json::boolean(matched))
325	    guard matched else {
326	      set_field(
327	        result,
328	        "evidence",
329	        unknown_activity("workspace_missing_or_replaced"),
330	      )
331	      save_diagnostic(
332	        "bulk-workspace",
333	        "skipped",
334	        error_type="workspace_missing_or_replaced",
335	        evidence=result,
336	        protected_secrets=secrets,
337	        environment=workspace_environment(state),
338	        recording=operation_recording(state),
339	      )
340	      return Some(result)
341	    }
342	    let status = workspace_status(state)
343	    set_field(result, "vmStatus", Json::string(status))
344	    let activity_pairing : Ref[String?] = { val: None, }
345	    let evidence = if status != "Running" {
346	      unknown_activity("workspace_not_running")
347	    } else if options.force || mode == "resume" {
348	      unknown_activity(
349	        if options.force {
350	          "forced_without_activity_check"
351	        } else {
352	          "resume_does_not_require_activity"
353	        },
354	      )
355	    } else {
356	      observe_activity(state, pairing_out=activity_pairing) catch {
357	        error =>
358	          unknown_activity(
359	            if activity_pairing.val is Some(_) {
360	              diagnostic_error(error, environment=workspace_environment(state))
361	            } else {
362	              workspace_error_detail(state, error)
363	            },
364	          )
365	      }
366	    }
367	    set_field(result, "activity", field(evidence, "activity").unwrap())
368	    let evidence_incomplete : Ref[Bool] = { val: false, }
369	    let safe_evidence = if status != "Running" ||
370	      options.force ||
371	      mode == "resume" {
372	      evidence
373	    } else {
374	      match
375	        saved_workspace_secrets(
376	          state,
377	          for_output=true,
378	          include_pairing=activity_pairing.val is None,
379	        ) {
380	        Some(values) => {
381	          if activity_pairing.val is Some(pairing) && pairing != "" {
382	            add_protected_secret(values, pairing)
383	          }
384	          diagnostic_json(
385	            evidence,
386	            workspace_environment(state),
387	            values,
388	            evidence_incomplete,
389	            0,
390	            stable_activity=true,
391	          )
392	        }
393	        None => {
394	          evidence_incomplete.val = true
395	          (
396	            {
397	              "activity": field(evidence, "activity").unwrap(),
398	              "reason": "activity details unavailable",
399	              "detailsTruncated": true,
400	            } : Json)
401	        }
402	      }
403	    }
404	    set_field(result, "evidence", safe_evidence)
405	    if evidence_incomplete.val {
406	      set_field(result, "evidenceTruncated", Json::boolean(true))
407	    }
408	    save_diagnostic(
409	      "bulk-observation",
410	      mode,
411	      tunnel_directory=required(state, "tunnelDirectory"),
412	      evidence=result,
413	      evidence_incomplete=evidence_incomplete.val,
414	      evidence_stable_activity=true,
415	      protected_secrets=secrets,
416	      environment=workspace_environment(state),
417	      recording=operation_recording(state),
418	    )
419	    if mode == "status" {
420	      set_field(result, "outcome", Json::string("observed"))
421	      save_diagnostic(
422	        "bulk-workspace",
423	        "observed",
424	        evidence=result,
425	        evidence_incomplete=evidence_incomplete.val,
426	        evidence_stable_activity=true,
427	        protected_secrets=secrets,
428	        environment=workspace_environment(state),
429	        recording=operation_recording(state),
430	      )
431	      return Some(result)
432	    }
433	    if mode == "stop" {
434	      if status == "Stopped" {
435	        set_field(result, "reason", Json::string("already_stopped"))
436	      } else if !options.force &&
437	        (
438	          status != "Running" ||
439	          field(evidence, "activity") != Some(Json::string("idle"))
440	        ) {
441	        set_field(result, "reason", Json::string("not_idle"))
442	      } else {
443	        let (scope, valid) = bulk_identity(state, options.provider)
444	        guard scope && valid else {
445	          raise AdapterError("Workspace changed before stop")
446	        }
447	        mutating = true
448	        pause_tunnel(state)
449	        defer unpause_tunnel(state)
450	        stop_workspace(state)
451	        set_field(result, "outcome", Json::string("success"))
452	      }
453	    } else if status == "Running" {
454	      set_field(result, "reason", Json::string("already_running"))
455	    } else if status != "Stopped" {
456	      set_field(result, "reason", Json::string("workspace_not_stopped"))
457	    } else {
458	      let (scope, valid) = bulk_identity(state, options.provider)
459	      guard scope && valid else {
460	        raise AdapterError("Workspace changed before resume")
461	      }
462	      mutating = true
463	      unpause_tunnel(state)
464	      ignore(
465	        devsy(
466	          state,
467	          [
468	            "--result-format", "json", "workspace", "up", "--id", id, "--ide-launch",
469	            "skip",
470	          ] +
471	          orca_storage_args(state),
472	          "workspace-resume",
473	        ),
474	      )
475	      set_field(result, "outcome", Json::string("success"))
476	      idle_reset(state, "workspace_resumed")
477	    }
478	  } catch {
479	    error => {
480	      set_field(
481	        result,
482	        "outcome",
483	        Json::string(if mutating { "failed" } else { "skipped" }),
484	      )
485	      let detail = workspace_error_detail(state, error)
486	      set_field(result, "evidence", unknown_activity(detail))
487	      set_field(result, "error", Json::string(detail))
488	    }
489	  }
490	  if mode == "resume" &&
491	    field(result, "outcome") == Some(Json::string("success")) {
492	    recover_connection(state) catch {
493	      error => {
494	        set_field(result, "outcome", Json::string("failed"))
495	        set_field(
496	          result,
497	          "error",
498	          Json::string(workspace_error_detail(state, error)),
499	        )
500	      }
501	    }
502	  }
503	  save_diagnostic(
504	    "bulk-workspace",
505	    mode,
506	    evidence=result,
507	    evidence_incomplete=field(result, "evidenceTruncated") ==
508	      Some(Json::boolean(true)),
509	    evidence_stable_activity=true,
510	    protected_secrets=secrets,
511	    environment=workspace_environment(state),
512	    recording=operation_recording(state),
513	  )
514	  Some(result)
515	}
