517	///|
518	pub async fn bulk(mode : String, args : Array[String]) -> Unit {
519	  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
520	  let mut failure_recorded = false
521	  let recording_allowed : Ref[Bool] = {
522	    val: @env.get_env_var("ORCA_ENV_DEVSY_RECORDING") != Some("0"),
523	  }
524	  errdefer (if !failure_recorded && @async.is_being_cancelled() {
525	    @async.protect_from_cancel(async fn() {
526	      save_diagnostic(
527	        "bulk",
528	        "cancelled",
529	        error_type="cancelled",
530	        recording=recording_allowed.val,
531	      )
532	    })
533	  })
534	  let mut failures = 0
535	  let error = try {
536	    failures = bulk_inner(mode, args, recording_allowed)
537	    None
538	  } catch {
539	    error => Some(error)
540	  }
541	  if error is Some(error) {
542	    save_command_failure("bulk", error, recording=recording_allowed.val)
543	    failure_recorded = true
544	    raise error
545	  }
546	  guard failures == 0 else {
547	    raise AdapterError("Some workspace operations failed")
548	  }
