1326	  let payload = @json.parse(input.text())
1327	  guard field(payload, "schemaVersion") == Some(Json::number(1)) else {
1328	    raise AdapterError("Invalid lifecycle payload schema")
1329	  }
1330	  let result = match field(payload, "recipeResult") {
1331	    Some(value) => value
1332	    None => raise AdapterError("Missing recipeResult")
1333	  }
1334	  let state = match field(result, "userData") {
1335	    Some(value) => value
1336	    None => raise AdapterError("Missing saved adapter state")
1337	  }
1338	  guard field(state, "adapterVersion") == Some(Json::number(1)) else {
1339	    raise AdapterError("Unsupported adapter state")
1340	  }
1341	  validate_state(state)
1342	  match workspace(state) {
1343	    Some(current) if field(current, "uid") == field(state, "workspaceUid") => ()
1344	    None if mode == "destroy" => ()
1345	    _ => raise AdapterError("Workspace missing or replaced")
1346	  }
1347	  (state, result)
1348	}
