1413	///|
1414	async fn execute_inner(mode : String) -> Unit {
1415	  notify(mode)
1416	  if mode == "create" ||
1417	    mode == "resume" ||
1418	    mode == "recover" ||
1419	    mode == "restart" {
1420	    save_diagnostic(
1421	      "connection-budget",
1422	      "selected",
1423	      timeout_ms=connection_timeout_ms(),
1424	    )
1425	  }
1426	  let started = @env.now()
1427	  let (state, previous, deadline) = if mode == "create" {
1428	    let (state, expires) = create_state()
1429	    (state, Json::null(), Some(expires))
1430	  } else {
1431	    let (state, previous) = if mode == "recover" || mode == "restart" {
1432	      connection_timeout(started + connection_timeout_ms().to_uint64(), async fn() {
1433	        lifecycle_state(mode)
1434	      })
1435	    } else {
1436	      lifecycle_state(mode)
1437	    }
1438	    (
1439	      state,
1440	      previous,
1441	      if mode == "recover" || mode == "restart" {
1442	        Some(started + connection_timeout_ms().to_uint64())
1443	      } else {
1444	        None
1445	      },
1446	    )
1447	  }
1448	  let operation = if mode == "resume" || mode == "suspend" || mode == "destroy" {
1449	    Some(connection_operation_lock(state))
1450	  } else {
1451	    None
1452	  }
1453	  defer (if operation is Some(lock) { lock.close() })
1454	  if mode == "resume" {
1455	    guard workspace(state) is Some(current) &&
1456	      field(current, "uid") == field(state, "workspaceUid") else {
1457	      raise AdapterError("Workspace missing or replaced before resume")
1458	    }
1459	    unpause_tunnel(state)
1460	  }
1461	  match mode {
1462	    "create" => {
1463	      create_recording.phase = "connection"
1464	      errdefer discard_created_workspace(state)
1465	      connection_timeout(deadline.unwrap(), async fn() {
1466	        codex_addon(state)
1467	        emit_connection(state, true, deadline?)
1468	      })
1469	    }
1470	    "resume" => {
1471	      ignore(
1472	        devsy(
1473	          state,
1474	          [
1475	            "--result-format",
1476	            "json",
1477	            "workspace",
1478	            "up",
1479	            required(state, "workspaceId"),
1480	            "--ide-launch",
1481	            "skip",
1482	          ] +
1483	          orca_storage_args(state),
1484	          "workspace-resume",
1485	        ),
1486	      )
1487	      let expires = connection_deadline()
1488	      idle_reset(state, "workspace_resumed")
1489	      connection_timeout(expires, async fn() {
1490	        let port = if required(state, "connection") == "orca-server" {
1491	          Some(reserve_server_port(state))
1492	        } else {
1493	          None
1494	        }
1495	        ensure_ssh_worker(state, port, deadline=expires)
1496	        codex_addon(state)
1497	        if required(state, "connection") == "orca-server" {
1498	          ignore(recover_server(state))
1499	        }
1500	        emit_connection(state, false, existing=previous, deadline=expires)
1501	      })
1502	    }
1503	    "recover" | "restart" => {
1504	      recover_connection(state, restart=mode == "restart", deadline?)
1505	      let connection = field(previous, "connection").unwrap()
1506	      write_connection(state, connection)
1507	    }
1508	    "suspend" => {
1509	      pause_tunnel(state)
1510	      defer unpause_tunnel(state)
1511	      stop_workspace(state)
1512	    }
1513	    "destroy" => {
1514	      pause_tunnel(state)
1515	      errdefer unpause_tunnel(state)
1516	      ignore(
1517	        devsy(
1518	          state,
1519	          [
1520	            "workspace",
1521	            "delete",
1522	            required(state, "workspaceId"),
1523	            "--ignore-not-found",
1524	          ],
1525	          "workspace-delete",
1526	        ),
1527	      )
1528	      cleanup_orca_volume(state)
1529	      if field(state, "tunnelDirectory") is Some(Json::String(directory)) {
1530	        for name in ["server-update-pending", "server-update-complete"] {
1531	          if @fs.exists(directory + "/" + name) {
1532	            @fs.remove(directory + "/" + name)
1533	          }
1534	        }
1535	      }
1536	      close_tunnel(state)
1537	    }
1538	    _ => raise AdapterError("Unknown command")
1539	  }
1540	  save_diagnostic(mode, "success")
1541	  progress_message(mode + ": done (" + progress_timing(progress_started) + ")")
1542	}
