1554	///|
1555	pub async fn execute(mode : String) -> Unit {
1556	  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
1557	  let mut failure_recorded = false
1558	  errdefer (if !failure_recorded && @async.is_being_cancelled() {
1559	    @async.protect_from_cancel(async fn() {
1560	      save_diagnostic(mode, "cancelled", error_type="cancelled")
1561	    })
1562	  })
1563	  execute_inner(mode) catch {
1564	    InvalidConfig(message) => {
1565	      let detail = diagnostic_error(InvalidConfig(message))
1566	      progress_message(detail + " (" + progress_timing(progress_started) + ")")
1567	      save_command_failure(mode, InvalidConfig(message))
1568	      failure_recorded = true
1569	      raise InvalidConfig(message)
1570	    }
1571	    AdapterError(message) => {
1572	      let detail = diagnostic_error(AdapterError(message))
1573	      progress_message(detail + " (" + progress_timing(progress_started) + ")")
1574	      save_command_failure(mode, AdapterError(message))
1575	      failure_recorded = true
1576	      raise AdapterError(message)
1577	    }
1578	    error => {
1579	      progress_message(
1580	        mode + ": failed (" + progress_timing(progress_started) + ")",
1581	      )
1582	      save_command_failure(mode, error)
1583	      failure_recorded = true
1584	      raise AdapterError(
1585	        mode +
1586	        " failed: unexpected runtime error; diagnostic run " +
1587	        recording_run_id,
1588	      )
1589	    }
1590	  }
1591	}
