489	///|
490	async fn supervise_transport(directory : String, force~ : Bool = false) -> Unit {
491	  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
492	  let recording = field(state, "recording") == Some(Json::boolean(true))
493	  let pid = @string.parse_int(required(state, "pid"))
494	  guard pid > 1 else { raise AdapterError("Invalid transport owner") }
495	  let owner = @string.parse_int(required(state, "ownerPid"))
496	  let owner_start = @string.parse_int64(required(state, "ownerStart"))
497	  guard owner > 1 && owner_start > 0 else {
498	    raise AdapterError("Invalid SSH owner identity")
499	  }
500	  let start = @string.parse_int64(required(state, "start"))
501	  save_diagnostic(
502	    "supervisor-transport",
503	    "started",
504	    evidence={
505	      "pid": pid,
506	      "start": start.to_string(),
507	      "ownerPid": owner,
508	      "ownerStart": owner_start.to_string(),
509	      "lease": field(state, "lease").unwrap_or(Json::null()),
510	    },
511	    recording~,
512	  )
513	  let reason : Ref[String] = { val: "supervisor_shutdown", }
514	  let mut detached = false
515	  defer @async.protect_from_cancel(async fn() {
516	    guard reason.val != "inspection_failed" else { return }
517	    if transport_group_alive(pid, start) {
518	      if reason.val != "transport_exited" {
519	        ignore(proxy_signal(-pid, 15))
520	        @async.sleep(500)
521	      }
522	      if transport_group_alive(pid, start) {
523	        ignore(proxy_signal(-pid, 9))
524	        @async.with_timeout(2000, async fn() {
525	          while transport_group_alive(pid, start) {
526	            @async.sleep(10)
527	          }
528	        })
529	      }
530	    }
531	    save_diagnostic(
532	      "ssh-proxy",
533	      "cleaned",
534	      evidence={ "pid": pid, "transport": directory, "reason": reason.val },
535	      recording~,
536	    )
537	    publish_file(directory + "/done", reason.val)
538	    @fs.rmdir(directory, recursive=true)
539	    save_diagnostic(
540	      "supervisor-transport",
541	      "stopped",
542	      evidence={ "pid": pid, "reason": reason.val },
543	      recording~,
544	    )
545	  })
546	  if force {
547	    return
548	  }
549	  while true {
550	    let owner_current = process_start(owner)
551	    let transport_current = process_start(pid)
552	    guard owner_current >= 0 && transport_current >= 0 else {
553	      raise AdapterError("Cannot inspect SSH transport identity")
554	    }
555	    if transport_current != start {
556	      reason.val = "transport_exited"
557	      return
558	    }
559	    if owner_current != owner_start {
560	      let closed = if field(state, "lease") != Some(Json::string("")) {
561	        1
562	      } else {
563	        transport_input_closed(pid)
564	      }
565	      guard closed >= 0 else {
566	        reason.val = "inspection_failed"
567	        let failure = match -closed / 65536 {
568	          1 => "pipe_info"
569	          2 => "pipe_info_short"
570	          3 => "input_open"
571	          4 => "input_stat"
572	          5 => "input_not_pipe"
573	          6 => "input_poll"
574	          _ => "input_poll_invalid"
575	        }
576	        save_diagnostic(
577	          "supervisor-transport",
578	          "inspection_failed",
579	          evidence={
580	            "pid": pid,
581	            "transport": directory,
582	            "failure": failure,
583	            "errno": -closed % 65536,
584	          },
585	          recording~,
586	        )
587	        return
588	      }
589	      if closed == 1 {
590	        reason.val = "owner_exited"
591	        return
592	      }
593	      if !detached {
594	        detached = true
595	        save_diagnostic(
596	          "supervisor-transport",
597	          "adopted",
598	          evidence={ "pid": pid, "reason": "ssh_owner_detached" },
599	          recording~,
600	        )
601	      }
602	    }
603	    @async.sleep(100)
604	  }
605	}
