   129	        )
   130	        .trim()
   131	        .to_owned()
   132	      match installation {
   133	        "installed" => ()
   134	        "missing" =>
   135	          ignore(remote(state, server_install_script(), "orca-install"))
   136	        _ => raise AdapterError("Invalid Orca installation probe result")
   137	      }
   138	    }
   139	    let launched = launch_server(state)
   140	    configure_orca_project(state)
   141	    launched
   142	  }
   143	  let observed = server_relay_check(
   144	    state,
   145	    if @fs.exists(pending) {
   146	      "verify-required"
   147	    } else {
   148	      "verify"
   149	    },
   150	    "server-relay-check",
   151	  )
   152	  let mut outcome = required(observed, "outcome")
   153	  if outcome == "mismatch" {
   154	    @fs.write_file(pending, "", permission=0o600)
   155	    let stopped = server_relay_check(state, "sync", "server-relay-stop")
   156	    outcome = required(stopped, "outcome")
   157	    guard field(observed, "relayInstance") == field(stopped, "relayInstance") else {
   158	      raise AdapterError("Orca relay instance changed during recovery")
   159	    }
   160	    if outcome == "restart" {
   161	      output = launch_server(state)
   162	      let verified = server_relay_check(
   163	        state, "verify-required", "server-relay-verify",
   164	      )
   165	      guard (
   166	          required(verified, "outcome") == "match" ||
   167	          (
   168	            required(verified, "outcome") == "skip" &&
   169	            field(stopped, "serverInstance") == Some(Json::string(""))
   170	          )
   171	        ) &&
   172	        field(stopped, "relayInstance") == field(verified, "relayInstance") else {
   173	        raise AdapterError(
   174	          "Orca relay instance changed or is unavailable after restart",
   175	        )
   176	      }
   177	      save_diagnostic(
   178	        "server-relay-sync",
   179	        "restarted",
   180	        tunnel_directory=directory,
   181	        recording=state_recording(state),
   182	      )
   183	    }
   184	  }
   185	  guard outcome == "restart" || outcome == "match" || outcome == "skip" else {
   186	    raise AdapterError("Cannot compare Orca relay instances")
   187	  }
   188	  if @fs.exists(pending) {
   189	    @fs.remove(pending)
   190	  }
   191	  @fs.write_file(directory + "/server-enabled", "", permission=0o600)
   192	  output
   193	}
   194	
   195	///|
   196	async fn launch_server(state : Json, update_marker? : (String, String)) -> Json {
   197	  let root = required(state, "projectRoot")
   198	  let port = reserve_server_port(state)
   199	  let configured_env = field(state, "serverEnv").unwrap_or(Json::empty_object())
   200	  let diagnostic_env = Json::empty_object()
   201	  if configured_env is Json::Object(values) {
   202	    for name, value in values {
   203	      if value is Json::String(text) {
   204	        set_field(diagnostic_env, name, Json::string(redact_credentials(text)))
   205	      }
   206	    }
   207	  }
   208	  let protected_values = workspace_output_secrets(state)
   209	  if protected_values is None {
   210	    suppress_workspace_recording(state)
   211	  }
   212	  let recording = state_recording(state)
   213	  let launch = (if field(state, "orcaVolume") is Some(_) {
   214	      "export ORCA_USER_DATA_PATH=/worktrees/.orca; "
   215	    } else {
   216	      ""
   217	    }) +
   218	    server_launch_script(root, port, configured_env, recording~, update_marker?)
   219	  let script = if update_marker is Some(_) {
   220	    server_update_locked(launch, inline_launch=true)
   221	  } else {
   222	    launch
   223	  }
   224	  let (status, raw_output, detail) = command_result(
   225	    workspace_program(state, "ssh"),
   226	    mux_ssh_args(state) + [script],
   227	    "orca-serve",
   228	    environment=workspace_environment(state),
   229	    recording_override=state_recording(state),
   230	    protected_secrets?=protected_values,
   231	    protection_incomplete=protected_values is None,
   232	    cwd?=workspace_directory(state).map(path => path[:]),
   233	  )
   234	  let mut output = raw_output
   235	  if recording {
   236	    let mut observed = None
   237	    let mut truncated = Json::array([])
   238	    let mut observation_error = false
   239	    if raw_output.split_once("\n") is Some((first, remaining)) {
   240	      let event = @json.parse(first.to_owned()) catch { _ => Json::null() }
   241	      if field(event, "kind") == Some(Json::string("result")) &&
   242	        field(event, "serverEnvironment") is Some(value) {
   243	        observed = Some(value)
   244	        truncated = field(event, "truncated").unwrap_or(Json::array([]))
   245	        observation_error = field(event, "observationError") ==
   246	          Some(Json::boolean(true))
   247	        output = remaining.to_owned()
   248	      }
   249	    }
   250	    let complete = (
   251	        configured_env == Json::empty_object() || observed is Some(_)
   252	      ) &&
   253	      truncated == Json::array([]) &&
   254	      !observation_error
   255	    let pairing = workspace_pairing_secrets(state)
   256	    if pairing is None {
   257	      suppress_workspace_recording(state)
   258	    }
   259	    save_diagnostic(
   260	      "server-environment",
   261	      if complete {
   262	        "observed"
   263	      } else {
   264	        "partial"
   265	      },
   266	      evidence={
   267	        "templates": diagnostic_env,
   268	        "references": observed.unwrap_or(Json::null()),
   269	        "completeness": if complete {
   270	          "complete"
   271	        } else {
   272	          "partial"
   273	        },
   274	        "missingReason": if complete {
   275	          Json::null()
   276	        } else if observed is None || observation_error {
   277	          "observation_failed"
   278	        } else {
   279	          "value_truncated"
   280	        },
   281	        "truncatedReferences": truncated,
   282	      },
   283	      evidence_incomplete=!complete,
   284	      protected_secrets?=pairing,
   285	      environment=workspace_environment(state),
   286	      recording=recording && pairing is Some(_),
   287	    )
   288	  }
   289	  guard status == 0 else {
   290	    raise AdapterError(command_failure("orca-serve", status, detail))
   291	  }
   292	  let result = @json.parse(output)
   293	  let connection = match field(result, "connection") {
   294	    Some(value) => value
   295	    None => result
   296	  }
   297	  guard required(connection, "pairingCode") != "" else {
   298	    raise AdapterError("Orca returned no pairing code")
   299	  }
   300	  @fs.write_file(
   301	    required(state, "tunnelDirectory") + "/pairing-code",
   302	    required(connection, "pairingCode"),
   303	    permission=0o600,
   304	  )
   305	  let output : Json = {
   306	    "type": "orca-server",
   307	    "pairingCode": required(connection, "pairingCode"),
   308	    "projectRoot": root,
   309	  }
   310	  output
   311	}
   312	
   313	///|
   314	fn shell_wait_with_signals(command : String) -> String {
   315	  "trap 'kill -s TERM \"$!\" 2>/dev/null || :; wait \"$!\" 2>/dev/null || :; exit 143' TERM; " +
   316	  "trap 'kill -s INT \"$!\" 2>/dev/null || :; wait \"$!\" 2>/dev/null || :; exit 130' INT; " +
   317	  "trap 'kill -s HUP \"$!\" 2>/dev/null || :; wait \"$!\" 2>/dev/null || :; exit 129' HUP; " +
   318	  command +
   319	  " & wait \"$!\""
   320	}
   321	
   322	///|
   323	fn server_launch_script(
   324	  root : String,
   325	  port : Int32,
   326	  server_env : Json,
   327	  recording~ : Bool = false,
   328	  update_marker? : (String, String),
   329	) -> String raise {
   330	  let names : Map[String, Bool] = Map([])
"}]}

