  1677	///|
  1678	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
  1679	  match value {
  1680	    None => { "state": "unset" }
  1681	    Some("") => { "state": "empty" }
  1682	    Some(text) => {
  1683	      let valid = match kind {
  1684	        Commit => valid_commit(text)
  1685	        Workspace => valid_workspace_id(text)
  1686	        Identity => text.length() <= 128 && valid_context(text)
  1687	        RefName => diagnostic_ref(text)
  1688	      }
  1689	      let credential_form = text
  1690	        .split("/")
  1691	        .iter()
  1692	        .any(part => {
  1693	          [
  1694	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
  1695	            "eyJ",
  1696	          ]
  1697	          .iter()
  1698	          .any(prefix => part.has_prefix(prefix))
  1699	        })
  1700	      if credential_form {
  1701	        { "state": "redacted" }
  1702	      } else if valid {
  1703	        { "state": "valid", "value": text }
  1704	      } else {
  1705	        { "state": "invalid", "value": text }
  1706	      }
  1707	    }
  1708	  }
  1709	}
