  1711	///|
  1712	// A recording grammar, never a replacement for checkout validation. Excludes
  1713	// URLs, credential forms, control characters and Git's invalid ref syntax.
  1714	fn diagnostic_ref(text : String) -> Bool {
  1715	  text.length() <= 1024 &&
  1716	  !text.has_prefix("-") &&
  1717	  !text.contains("..") &&
  1718	  !text.contains("@{") &&
  1719	  text != "@" &&
  1720	  text
  1721	  .split("/")
  1722	  .iter()
  1723	  .all(part => {
  1724	    part != "" &&
  1725	    !part.has_prefix(".") &&
  1726	    !part.has_suffix(".") &&
  1727	    !part.has_suffix(".lock")
  1728	  }) &&
  1729	  text
  1730	  .iter()
  1731	  .all(c => {
  1732	    c > ' ' &&
  1733	    c != '\u007f' &&
  1734	    !['~', '^', ':', '?', '*', '[', '\\'].contains(c)
  1735	  })
  1736	}
