  1839	///|
  1840	// Inspect only the strategy flags in the actual invocation. Other arguments
  1841	// never enter the diagnostic record. Devsy uses the last valid repeated flag.
  1842	fn diagnostic_clone_strategy(args : Array[String]) -> (String, String) {
  1843	  let mut strategy = "full"
  1844	  let mut count = 0
  1845	  let mut invalid = false
  1846	  let mut index = 0
  1847	  while index < args.length() {
  1848	    let argument = args[index]
  1849	    let value = if argument == "--git-clone-strategy" {
  1850	      count += 1
  1851	      index += 1
  1852	      if index < args.length() {
  1853	        Some(args[index])
  1854	      } else {
  1855	        None
  1856	      }
  1857	    } else if argument.has_prefix("--git-clone-strategy=") {
  1858	      count += 1
  1859	      Some(argument[21:].to_owned())
  1860	    } else {
  1861	      None
  1862	    }
  1863	    if count > 0 &&
  1864	      (
  1865	        argument == "--git-clone-strategy" ||
  1866	        argument.has_prefix("--git-clone-strategy=")
  1867	      ) {
  1868	      match value {
  1869	        Some("") => strategy = "full"
  1870	        Some("shallow" | "blobless" | "treeless" | "bare" as known) =>
  1871	          strategy = known
  1872	        _ => invalid = true
  1873	      }
  1874	    }
  1875	    index += 1
