   248	///|
   249	fn registration_id_valid(id : String) -> Bool {
   250	  id.length() > 0 &&
   251	  id.length() <= 80 &&
   252	  id.iter().all(c => (c >= '0' && c <= '9') || c == '_' || c == ':')
   253	}
