   213	///|
   214	async fn read_codex_auth(home : String) -> CodexAuth {
   215	  guard @fs.file_size(home + "/auth.json") <= 65536L else {
   216	    raise AdapterError("Invalid Codex auth size")
   217	  }
   218	  let source = @fs.read_file(home + "/auth.json")
   219	  guard source.binary().length() <= 65536 else {
   220	    raise AdapterError("Invalid Codex auth size")
   221	  }
   222	  let auth = @json.parse(source.text())
   223	  guard (
   224	      field(auth, "OPENAI_API_KEY") == None ||
   225	      field(auth, "OPENAI_API_KEY") == Some(Json::null())
   226	    ) &&
   227	    (
   228	      field(auth, "auth_mode") == None ||
   229	      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
   230	    ) else {
   231	    raise AdapterError("Unsupported Codex auth mode")
   232	  }
   233	  guard field(auth, "tokens") is Some(tokens) else {
   234	    raise AdapterError("Missing Codex auth tokens")
   235	  }
   236	  let access = required(tokens, "access_token")
   237	  let secrets = [access]
   238	  for name in ["id_token", "refresh_token"] {
   239	    if field(tokens, name) is Some(Json::String(value)) && value != "" {
   240	      secrets.push(value)
   241	    }
   242	  }
   243	  let segments = access.split(".").to_array()
   244	  guard segments.length() == 3 else {
   245	    raise AdapterError("Invalid access token")
   246	  }
   247	  let encoded = segments[1]
   248	    .to_owned()
   249	    .replace_all(old="-", new="+")
   250	    .replace_all(old="_", new="/")
   251	  let padding = (4 - encoded.length() % 4) % 4
   252	  let claims = @json.parse(
   253	    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
   254	  )
   255	  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
   256	    raise AdapterError("Invalid access token expiry")
   257	  }
   258	  { access, account: required(tokens, "account_id"), expiry, secrets, }
   259	}
