   262	async fn codex_rpc_response(
   263	  reader : @process.ReadFromProcess,
   264	  id : Int32,
   265	  secrets : Array[String],
   266	) -> Unit {
   267	  let bytes : Array[Byte] = []
   268	  let mut total = 0
   269	  while true {
