   205	///|
   206	priv struct CodexAuth {
   207	  access : String
   208	  account : String
   209	  expiry : Double
   210	  secrets : Array[String]
   211	}
   212	
   213	///|
   214	async fn read_codex_auth(home : String) -> CodexAuth {
   215	  guard @fs.file_size(home + "/auth.json") <= 65536L else {
   216	    raise AdapterError("Invalid Codex auth size")
   217	  }
   218	  let source = @fs.read_file(home + "/auth.json")
   219	  guard source.binary().length() <= 65536 else {
   220	    raise AdapterError("Invalid Codex auth size")
   221	  }
   222	  let auth = @json.parse(source.text())
   223	  guard (
   224	      field(auth, "OPENAI_API_KEY") == None ||
   225	      field(auth, "OPENAI_API_KEY") == Some(Json::null())
   226	    ) &&
   227	    (
   228	      field(auth, "auth_mode") == None ||
   229	      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
   230	    ) else {
   231	    raise AdapterError("Unsupported Codex auth mode")
   232	  }
   233	  guard field(auth, "tokens") is Some(tokens) else {
   234	    raise AdapterError("Missing Codex auth tokens")
   235	  }
   236	  let access = required(tokens, "access_token")
   237	  let secrets = [access]
   238	  for name in ["id_token", "refresh_token"] {
   239	    if field(tokens, name) is Some(Json::String(value)) && value != "" {
   240	      secrets.push(value)
   241	    }
   242	  }
   243	  let segments = access.split(".").to_array()
   244	  guard segments.length() == 3 else {
   245	    raise AdapterError("Invalid access token")
   246	  }
   247	  let encoded = segments[1]
   248	    .to_owned()
   249	    .replace_all(old="-", new="+")
   250	    .replace_all(old="_", new="/")
   251	  let padding = (4 - encoded.length() % 4) % 4
   252	  let claims = @json.parse(
   253	    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
   254	  )
   255	  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
   256	    raise AdapterError("Invalid access token expiry")
   257	  }
   258	  { access, account: required(tokens, "account_id"), expiry, secrets, }
   259	}
   260	
   261	///|
   262	async fn codex_rpc_response(
   263	  reader : @process.ReadFromProcess,
   264	  id : Int32,
   265	  secrets : Array[String],
   266	) -> Unit {
   267	  let bytes : Array[Byte] = []
   268	  let mut total = 0
   269	  while true {
   270	    let byte = reader.read_exactly(1)[0]
   271	    total += 1
   272	    guard total <= 1048576 else {
   273	      raise AdapterError("Codex refresh output limit")
   274	    }
   275	    if byte == b'\n' {
   276	      let response = @json.parse(@utf8.decode(Bytes::from_array(bytes)))
   277	      bytes.clear()
   278	      if field(response, "id") == Some(Json::number(id.to_double())) {
   279	        if field(response, "error") is Some(error) {
   280	          let code = match field(error, "code") {
   281	            Some(Json::Number(value, ..)) => " code " + value.to_string()
   282	            _ => ""
   283	          }
   284	          let message = match field(error, "message") {
   285	            Some(Json::String(value)) =>
   286	              ": " + diagnostic_text(value, protected_secrets=secrets)
   287	            _ => ""
   288	          }
   289	          raise AdapterError("Codex refresh RPC \{id} failed" + code + message)
   290	        }
   291	        guard field(response, "result") != None else {
   292	          raise AdapterError("Codex refresh RPC \{id} returned no result")
   293	        }
   294	        return
   295	      }
   296	    } else {
   297	      bytes.push(byte)
   298	    }
   299	  }
   300	}
   301	
   302	///|
   303	async fn refresh_codex(home : String, secrets : Array[String]) -> Unit {
   304	  let (reader, output) = @process.read_from_process()
   305	  defer reader.close()
   306	  let (input, writer) = @process.write_to_process()
   307	  defer writer.close()
   308	  let (errors, stderr) = @process.read_from_process()
   309	  defer errors.close()
   310	  let captured = @buffer.Buffer(size_hint=1024)
   311	  let incomplete : Ref[Bool] = { val: false, }
   312	  let finished : Ref[Bool] = { val: false, }
   313	  let failure = try {
   314	    @async.with_task_group(async fn(group) {
   315	      ignore(
   316	        @process.spawn(
   317	          group,
   318	          "codex",
   319	          ["app-server", "--stdio"],
   320	          extra_env={ "CODEX_HOME": home },
   321	          stdin=input,
   322	          stdout=output,
   323	          stderr~,
   324	          no_wait=true,
   325	        ),
   326	      )
   327	      group.spawn_bg(no_wait=true, async fn() {
   328	        while errors.read_some(max_len=4096) is Some(chunk) {
   329	          let remaining = 8192 - captured.length()
   330	          let count = if chunk.length() < remaining {
   331	            chunk.length()
   332	          } else {
   333	            remaining
   334	          }
   335	          if count > 0 {
   336	            captured.write_bytes(chunk[:count])
   337	          }
   338	          if count < chunk.length() {
   339	            incomplete.val = true
   340	          }
   341	        }
   342	        finished.val = true
   343	      })
   344	      let initialize : Json = {
   345	        "id": 1,
   346	        "method": "initialize",
   347	        "params": {
   348	          "clientInfo": { "name": "orca-env-devsy", "version": version },
   349	        },
   350	      }
   351	      writer.write(initialize.stringify() + "\n")
   352	      codex_rpc_response(reader, 1, secrets)
   353	      writer.write("{\"method\":\"initialized\"}\n")
   354	      writer.write(
   355	        "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
   356	      )
   357	      codex_rpc_response(reader, 2, secrets)
   358	    })
   359	    None
   360	  } catch {
   361	    error => Some(error)
   362	  }
   363	  if failure is Some(error) {
   364	    if @async.is_being_cancelled() {
   365	      raise error
   366	    }
   367	    let protected_input : Json = { "access_token": secrets }
   368	    let detail = diagnostic_output(
   369	      captured.to_bytes(),
   370	      @env.get_env_vars(),
   371	      protected_input=protected_input.stringify(),
   372	      omitted=incomplete.val || !finished.val,
   373	    )
   374	    raise AdapterError(
   375	      diagnostic_error(error) +
   376	      detail
   377	      .map(value => "\nCodex app-server stderr: " + value)
   378	      .unwrap_or(
   379	        if finished.val {
   380	          ""
   381	        } else {
   382	          "\n[Codex app-server stderr incomplete]"
   383	        },
   384	      ),
   385	    )
   386	  }
   387	}
   388	
   389	///|
   390	async fn codex_credentials(home : String, recording~ : Bool) -> CodexAuth {
   391	  let initial = read_codex_auth(home)
   392	  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
   393	    return initial
   394	  }
   395	  let lock = @fs.open(
   396	    home + "/.orca-env-devsy-refresh.lock",
   397	    mode=ReadWrite,
   398	    create_mode=OpenOrCreate,
   399	    permission=0o600,
   400	  )
   401	  defer lock.close()
   402	  while !lock.try_lock(Exclusive) {
   403	    @async.sleep(100)
   404	  }
   405	  let before = read_codex_auth(home)
   406	  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
   407	    return before
   408	  }
   409	  let mut phase = "refresh"
   410	  try {
   411	    refresh_codex(home, before.secrets)
   412	    phase = "verify"
   413	    let after = read_codex_auth(home)
   414	    guard after.access != before.access && after.expiry > before.expiry else {
   415	      raise AdapterError("Codex refresh not persisted")
   416	    }
   417	    save_diagnostic("codex-refresh", "success", recording~)
   418	  } catch {
   419	    error => {
   420	      progress_write(
   421	        "orca-env-devsy: warning: Codex refresh failed; checking remaining token lifetime\n",
   422	      )
   423	      let detail = diagnostic_error(error)
   424	      save_diagnostic(
   425	        "codex-refresh",
   426	        "warning",
   427	        phase~,
   428	        error_type=if error is @async.TimeoutError {
   429	          "timeout"
   430	        } else {
   431	          "refresh_failed"
   432	        },
   433	        error_message=detail,
   434	        recording~,
   435	      )
   436	    }
   437	  }
   438	  let current = read_codex_auth(home)
   439	  guard current.expiry > @env.now().to_double() / 1000 else {
   440	    raise AdapterError("Expired access token")
   441	  }
   442	  if current.expiry - @env.now().to_double() / 1000 < 604800 {
   443	    progress_write(
   444	      "orca-env-devsy: warning: Codex token has less than seven days remaining\n",
   445	    )
   446	  }
   447	  current
   448	}

